/**
 * What the app knows about the account's AI card allowance.
 *
 * The server enforces the daily and monthly allowances. Since 21 Oct 2026
 * the numbers are public (owner), so the server also reports them: the
 * account's own `aiCards` object (limits, what is used, when each renews) on
 * GET /billing/state and in the body of the 429 that refuses a card, and a
 * finished AI job's `usage`. This module keeps the last report in IndexedDB
 * meta, so the add sheet can draw "3 AI cards left today" on its first frame
 * without a request, and records a refusal so the app rests until the
 * allowance that ran out renews.
 *
 * Every number is optional. An older server sends none of them, and then
 * the screens say something true without a number: never "until tomorrow"
 * when the allowance that ran out might be the month's.
 */
import { isApiError } from '@/api/errors.js';
import { db, getMeta, setMeta, type StoredAiAllowance } from '@/db/schema.js';

/** The allowance as the server sends it (`aiCards`), every field optional. */
export type AiAllowance = Omit<StoredAiAllowance, 'seenAt'>;

/** Which allowance ran out: the day's or the month's. */
export type AiPauseKind = 'day' | 'month';

/** Midnight UTC after `now`, when the daily allowance renews. */
export function nextUtcMidnight(now: Date = new Date()): Date {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1));
}

/** The first instant of the next UTC month, when the monthly allowance renews. */
export function nextUtcMonth(now: Date = new Date()): Date {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1));
}

/** True for the server's "not now" on an AI request. */
export function isRefusal(cause: unknown): boolean {
  return isApiError(cause) && cause.status === 429;
}

const count = (value: unknown): number | undefined =>
  typeof value === 'number' && Number.isInteger(value) && value >= 0 ? value : undefined;

const instant = (value: unknown): string | undefined =>
  typeof value === 'string' && !Number.isNaN(Date.parse(value)) ? new Date(value).toISOString() : undefined;

/**
 * The allowance in whatever the server sent, or undefined when it holds
 * nothing usable. Anything of the wrong type is dropped field by field: a
 * malformed number must never be printed.
 */
export function readAllowance(raw: unknown): AiAllowance | undefined {
  if (raw === null || typeof raw !== 'object') return undefined;
  const source = raw as Record<string, unknown>;
  const out: AiAllowance = {};
  const dailyLimit = count(source.dailyLimit);
  const dailyUsed = count(source.dailyUsed);
  const monthlyLimit = count(source.monthlyLimit);
  const monthlyUsed = count(source.monthlyUsed);
  const resetsDailyAt = instant(source.resetsDailyAt);
  const resetsMonthlyAt = instant(source.resetsMonthlyAt);
  if (dailyLimit !== undefined) out.dailyLimit = dailyLimit;
  if (dailyUsed !== undefined) out.dailyUsed = dailyUsed;
  // 0 means the plan has no monthly limit: nothing to count down from.
  if (monthlyLimit !== undefined && monthlyLimit > 0) {
    out.monthlyLimit = monthlyLimit;
    if (monthlyUsed !== undefined) out.monthlyUsed = monthlyUsed;
  }
  if (resetsDailyAt !== undefined) out.resetsDailyAt = resetsDailyAt;
  if (resetsMonthlyAt !== undefined) out.resetsMonthlyAt = resetsMonthlyAt;
  return Object.keys(out).length === 0 ? undefined : out;
}

/** The `aiCards` object a response carries (billing state, a 429 body), if any. */
export function allowanceIn(body: unknown): AiAllowance | undefined {
  if (body === null || typeof body !== 'object') return undefined;
  return readAllowance((body as { aiCards?: unknown }).aiCards);
}

/**
 * Keeps what the server reported, merged over what was known: a job's
 * usage carries the day's numbers but not the month's limit, and must not
 * erase it.
 */
export async function noteAllowance(next: AiAllowance | undefined, now: Date = new Date()): Promise<void> {
  if (next === undefined) return;
  await db.transaction('rw', db.meta, async () => {
    const stored = await getMeta('aiAllowance');
    const merged: StoredAiAllowance = { ...(stored ?? {}), ...next, seenAt: now.toISOString() };
    await setMeta('aiAllowance', merged);
    // A report that says there is room again ends a rest recorded earlier: a
    // purchase, a trial or an operator's change lifts it before the clock does.
    const left = cardsLeft(merged, now);
    if (left !== undefined && left.left > 0 && (await getMeta('aiPausedUntil')) !== null) {
      await setMeta('aiPausedUntil', null);
      await setMeta('aiPauseKind', null);
    }
  });
}

/** A finished job's `usage`: the day's count and limit, and the month's count. */
export async function noteUsage(
  usage: { cardsToday: number; dailyLimit: number; cardsThisMonth?: number | undefined } | undefined,
  now: Date = new Date(),
): Promise<void> {
  if (usage === undefined || usage.dailyLimit <= 0) return;
  const next: AiAllowance = {
    dailyLimit: usage.dailyLimit,
    dailyUsed: usage.cardsToday,
    resetsDailyAt: nextUtcMidnight(now).toISOString(),
  };
  if (usage.cardsThisMonth !== undefined) next.monthlyUsed = usage.cardsThisMonth;
  await noteAllowance(next, now);
}

/**
 * Which allowance a report says is spent: the month's wins, because it is
 * the one that does not renew tonight.
 */
export function spentKind(allowance: AiAllowance | undefined): AiPauseKind | undefined {
  if (allowance === undefined) return undefined;
  const { monthlyLimit, monthlyUsed, dailyLimit, dailyUsed } = allowance;
  if (monthlyLimit !== undefined && monthlyUsed !== undefined && monthlyUsed >= monthlyLimit) return 'month';
  if (dailyLimit !== undefined && dailyUsed !== undefined && dailyUsed >= dailyLimit) return 'day';
  return undefined;
}

/**
 * Records a refusal, so the app rests until the allowance renews. With the
 * server's numbers it rests until the exact renewal of the one that ran out;
 * without them, until the next UTC midnight, when asking again is cheap and
 * honest (the server refuses again if it was the month's), and the screens
 * name no day.
 */
export async function noteRefusal(cause: unknown, now: Date = new Date()): Promise<void> {
  if (!isRefusal(cause)) return;
  const body = isApiError(cause) ? (cause.problem as { aiCards?: unknown } | undefined)?.aiCards : undefined;
  const allowance = readAllowance(body);
  // The server names the limit that refused this request and when it opens
  // again; an older server only sends the counts, from which it is worked out.
  const named = body !== null && typeof body === 'object' ? (body as Record<string, unknown>) : {};
  const limitedBy = named.limitedBy;
  const kind: AiPauseKind | undefined =
    limitedBy === 'daily'
      ? 'day'
      : limitedBy === 'monthly'
        ? 'month'
        : limitedBy === undefined
          ? spentKind(allowance)
          : undefined;
  const again = instant(named.availableAgainAt);
  const until =
    again ??
    (kind === 'month'
      ? (allowance?.resetsMonthlyAt ?? nextUtcMonth(now).toISOString())
      : kind === 'day'
        ? (allowance?.resetsDailyAt ?? nextUtcMidnight(now).toISOString())
        : nextUtcMidnight(now).toISOString());
  // One transaction, so a screen watching these never sees the rest
  // without its kind.
  await db.transaction('rw', db.meta, async () => {
    if (allowance !== undefined) {
      const stored = await getMeta('aiAllowance');
      await setMeta('aiAllowance', { ...(stored ?? {}), ...allowance, seenAt: now.toISOString() });
    }
    await setMeta('aiPausedUntil', until);
    await setMeta('aiPauseKind', kind ?? null);
  });
}

/** When AI cards come back, or undefined when they are available. */
export async function aiPausedUntil(now: Date = new Date()): Promise<Date | undefined> {
  const stored = await getMeta('aiPausedUntil');
  if (typeof stored !== 'string') return undefined;
  const until = new Date(stored);
  return until.getTime() > now.getTime() ? until : undefined;
}

/**
 * The rest the app is in, with what a screen needs to say it exactly: when
 * it ends, which allowance it was, and that allowance's size. `kind` and
 * `limit` are absent when the server did not say.
 */
export interface AiRest {
  until: Date;
  kind?: AiPauseKind;
  limit?: number;
}

/**
 * The current rest, or undefined while AI cards are available. Only a
 * refusal starts one: a report with nothing left is not enough, because
 * cards an operator gave as a gift are not in it and may still be there.
 */
export async function aiRest(now: Date = new Date()): Promise<AiRest | undefined> {
  const until = await aiPausedUntil(now);
  if (until === undefined) return undefined;
  const kind = await getMeta('aiPauseKind');
  const allowance = await getMeta('aiAllowance');
  const rest: AiRest = { until };
  if (kind === 'day' || kind === 'month') {
    rest.kind = kind;
    const limit = kind === 'day' ? allowance?.dailyLimit : allowance?.monthlyLimit;
    if (limit !== undefined) rest.limit = limit;
  }
  return rest;
}

/** How many AI cards are left, and in which allowance, when that is known. */
export interface CardsLeft {
  left: number;
  period: AiPauseKind;
}

/**
 * The cards left, from the last report, or undefined when it is not known
 * now. A daily count is only trusted until the day it was counted in ends
 * (after that the day's use is zero, and the limit alone is the answer); a
 * monthly count likewise. The smaller of the two wins, because it is the
 * one the learner will meet first.
 */
export function cardsLeft(
  allowance: StoredAiAllowance | null | undefined,
  now: Date = new Date(),
): CardsLeft | undefined {
  if (allowance === null || allowance === undefined) return undefined;
  const seen = new Date(allowance.seenAt);
  const fresh = (resets: string | undefined, fallback: Date): boolean =>
    now.getTime() < (resets === undefined ? fallback.getTime() : Date.parse(resets));
  const options: CardsLeft[] = [];
  if (allowance.dailyLimit !== undefined) {
    const used = fresh(allowance.resetsDailyAt, nextUtcMidnight(seen)) ? allowance.dailyUsed : 0;
    if (used !== undefined) options.push({ left: Math.max(0, allowance.dailyLimit - used), period: 'day' });
  }
  if (allowance.monthlyLimit !== undefined) {
    const used = fresh(allowance.resetsMonthlyAt, nextUtcMonth(seen)) ? allowance.monthlyUsed : 0;
    if (used !== undefined)
      options.push({ left: Math.max(0, allowance.monthlyLimit - used), period: 'month' });
  }
  return options.reduce<CardsLeft | undefined>(
    (best, one) => (best === undefined || one.left < best.left ? one : best),
    undefined,
  );
}

/** The cards left right now, read from meta, for a screen's first frame. */
export async function aiCardsLeft(now: Date = new Date()): Promise<CardsLeft | undefined> {
  return cardsLeft(await getMeta('aiAllowance'), now);
}

/** At or under this, the add sheet quietly says how many AI cards are left. */
export const FEW_CARDS_LEFT = 3;
